import os
paper_dir = '/home/ubuntu/.agent-ml-research-idea_gen_0509_12/projects/simgate-modular-routing/docs/paper'
for f in os.listdir(paper_dir):
    fp = os.path.join(paper_dir, f)
    if os.path.isfile(fp):
        try:
            data = open(fp, 'rb').read()
            for i, b in enumerate(data):
                if b > 127:
                    # try to decode context
                    start = max(0, i-20)
                    end = min(len(data), i+20)
                    print(f'{f}:{i}: byte 0x{b:02x}, context: {data[start:end]}')
                    break
        except:
            pass
print('Done')
